@import "tailwindcss";

/*
 * The shadcn "radix-nova" primitives are written against `data-checked:` / `data-open:` rather
 * than `data-[state=checked]:`. Radix emits one `data-state` attribute, so those class names only
 * resolve once the project declares the variants — without this the switches render invisible.
 */
@custom-variant data-checked (&[data-state="checked"]);
@custom-variant data-unchecked (&[data-state="unchecked"]);
@custom-variant data-open (&[data-state="open"]);
@custom-variant data-closed (&[data-state="closed"]);

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-destructive: var(--destructive);

  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
}

:root {
  --radius: 0.625rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.556 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --accent: oklch(0.97 0 0);
  --accent-foreground: oklch(0.205 0 0);
  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.708 0 0);
  --destructive: oklch(0.577 0.245 27.325);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }

  html {
    color-scheme: light;
  }

  body {
    @apply bg-background text-foreground;
    margin: 0;
    min-width: 320px;
    overflow: hidden;
    font-family:
      -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Arial,
      sans-serif;
    font-synthesis: none;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }

  button:not(:disabled),
  [role="button"]:not(:disabled) {
    cursor: pointer;
  }
}

.session-canvas {
  position: relative;
  min-height: 100dvh;
  overflow: hidden;
  color: #111111;
  background: #f7f7f5;
}

.glia-wordmark {
  position: fixed;
  top: 27px;
  left: 30px;
  z-index: 70;
  color: #111111;
  font-size: 21px;
  font-weight: 650;
  letter-spacing: -0.065em;
  line-height: 1;
  text-decoration: none;
}

/*
 * The only persistent control in the app. It sits outside both phase layouts, so neither the
 * hero card nor the workspace grid can be moved by it, and it rests near-invisible: somebody who
 * never looks for it should never notice it is there.
 */
.session-settings {
  position: fixed;
  top: 27px;
  right: 30px;
  z-index: 70;
  display: grid;
  width: 28px;
  height: 28px;
  padding: 0;
  place-items: center;
  color: #111111;
  background: transparent;
  border: 0;
  border-radius: 999px;
  opacity: 0.26;
  transition-property: opacity;
  transition-duration: 160ms;
  transition-timing-function: cubic-bezier(0.2, 0, 0, 1);
}

.session-settings svg {
  width: 16px;
  height: 16px;
}

.session-settings:hover,
.session-settings[data-state="open"] {
  opacity: 0.72;
}

.session-settings:focus-visible {
  opacity: 0.72;
  outline: 3px solid rgb(49 89 215 / 25%);
  outline-offset: 2px;
}

.settings-dialog {
  width: min(420px, calc(100vw - 32px));
  max-width: none;
  gap: 22px;
  padding: 26px 26px 28px;
  color: #111111;
  background: #ffffff;
  border-radius: 18px;
  box-shadow:
    0 1px 1px rgb(17 17 17 / 5%),
    0 12px 34px rgb(17 17 17 / 11%),
    0 34px 80px rgb(17 17 17 / 9%);
}

.settings-body {
  display: flex;
  flex-direction: column;
  gap: 26px;
}

.settings-group {
  display: flex;
  flex-direction: column;
  gap: 13px;
}

.settings-group-label {
  margin: 0;
  color: #8f8f8f;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.09em;
  line-height: 1;
  text-transform: uppercase;
}

.settings-row {
  display: flex;
  gap: 16px;
  align-items: center;
  justify-content: space-between;
}

.settings-row-text {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

.settings-row-label {
  font-size: 14px;
  font-weight: 500;
  letter-spacing: -0.015em;
  line-height: 1.2;
}

.settings-note {
  margin: 0;
  color: #8f8f8f;
  font-size: 12px;
  font-weight: 430;
  letter-spacing: -0.01em;
  line-height: 1.3;
  text-wrap: pretty;
}

.settings-segmented {
  display: grid;
  gap: 3px;
  grid-auto-columns: 1fr;
  grid-auto-flow: column;
  padding: 3px;
  background: #f2f2f0;
  border-radius: 11px;
}

.settings-segment {
  padding: 7px 0;
  color: #6f6f6f;
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: -0.015em;
  background: transparent;
  border: 0;
  border-radius: 8px;
  transition-property: color, background-color, box-shadow;
  transition-duration: 150ms;
  transition-timing-function: cubic-bezier(0.2, 0, 0, 1);
}

.settings-segment[data-state="checked"] {
  color: #111111;
  background: #ffffff;
  box-shadow:
    0 0 0 1px rgb(17 17 17 / 6%),
    0 1px 3px rgb(17 17 17 / 10%);
}

.settings-segment:disabled {
  color: #bcbcbc;
  cursor: not-allowed;
}

.settings-segment:focus-visible {
  outline: 3px solid rgb(49 89 215 / 25%);
  outline-offset: -1px;
}

.settings-select {
  min-width: 132px;
}

/*
 * The portal lands on `body`, outside the canvas, so it has to clear the fixed chrome inside it:
 * the docked microphone sits at 60 and the wordmark at 70.
 */
[data-slot="dialog-overlay"] {
  z-index: 200;
  animation: settings-overlay-enter 160ms cubic-bezier(0.2, 0, 0, 1) both;
}

[data-slot="select-content"] {
  z-index: 220;
}

/*
 * Only opacity and scale: the centring lives on the `translate` property, which Tailwind writes
 * separately, so animating `transform` here cannot knock the panel off centre.
 */
[data-slot="dialog-content"] {
  z-index: 210;
  animation: settings-dialog-enter 200ms cubic-bezier(0.2, 0, 0, 1) both;
}

@keyframes settings-overlay-enter {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes settings-dialog-enter {
  from {
    opacity: 0;
    transform: scale(0.97);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.session-hero {
  position: fixed;
  top: 40%;
  left: 50%;
  z-index: 10;
  width: min(880px, calc(100vw - 48px));
  text-align: center;
  transform: translate(-50%, -50%);
  transition-property: opacity, transform, filter;
  transition-duration: 520ms;
  transition-timing-function: cubic-bezier(0.2, 0, 0, 1);
}

.session-hero[data-hidden="true"] {
  pointer-events: none;
  opacity: 0;
  filter: blur(4px);
  transform: translate(-50%, calc(-50% - 18px)) scale(0.98);
}

.session-hero > p:first-child {
  margin: 0 0 22px;
  color: #888888;
  font-size: 13px;
  font-weight: 550;
  letter-spacing: 0.015em;
}

.session-hero h1 {
  margin: 0;
  font-size: clamp(58px, 8vw, 112px);
  font-weight: 620;
  letter-spacing: -0.075em;
  line-height: 0.88;
  text-wrap: balance;
}

.session-hero > p:last-child {
  max-width: 460px;
  margin: 26px auto 0;
  color: #6f6f6f;
  font-size: clamp(16px, 1.5vw, 19px);
  font-weight: 430;
  letter-spacing: -0.025em;
  line-height: 1.35;
  text-wrap: balance;
}

.session-workspace {
  display: grid;
  width: 100%;
  height: 100dvh;
  grid-template-columns: minmax(320px, 0.85fr) 2fr;
  animation: workspace-enter 460ms cubic-bezier(0.2, 0, 0, 1) both;
}

.transcript-column {
  display: flex;
  min-height: 0;
  flex-direction: column;
  padding: 96px 28px 112px;
}

.transcript-scroll {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  justify-content: flex-end;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: none;
}

.session-mic {
  position: fixed;
  top: 67%;
  left: 50%;
  z-index: 60;
  display: flex;
  width: 260px;
  height: 64px;
  gap: 12px;
  align-items: center;
  justify-content: flex-start;
  padding: 8px 15px 8px 8px;
  color: #111111;
  background: rgb(255 255 255 / 95%);
  border: 1px solid rgb(17 17 17 / 7%);
  border-radius: 999px;
  box-shadow:
    0 1px 1px rgb(17 17 17 / 5%),
    0 9px 28px rgb(17 17 17 / 9%),
    0 26px 64px rgb(17 17 17 / 6%);
  transform: translate(-50%, -50%);
  scale: 1;
  transition-property: transform, scale, width, color, background-color, border-color, box-shadow;
  transition-duration: 680ms, 120ms, 360ms, 150ms, 150ms, 150ms, 280ms;
  transition-timing-function: cubic-bezier(0.2, 0, 0, 1);
}

.session-mic:hover {
  border-color: rgb(17 17 17 / 14%);
  box-shadow:
    0 1px 1px rgb(17 17 17 / 6%),
    0 12px 34px rgb(17 17 17 / 11%),
    0 30px 72px rgb(17 17 17 / 8%);
}

.session-mic:active {
  translate: 0;
  scale: 0.96;
}

.session-mic:focus-visible {
  outline: 3px solid rgb(49 89 215 / 25%);
  outline-offset: 3px;
}

.session-mic[data-docked="true"] {
  width: min(164px, calc(29vw - 56px));
  transform: translate(calc(-50vw + 28px), calc(33dvh - 28px - 100%));
}

.session-mic.is-listening {
  color: #ffffff;
  background: #111111;
  border-color: #111111;
}

.session-mic-orb {
  display: grid;
  flex: 0 0 auto;
  width: 46px;
  height: 46px;
  place-items: center;
  color: #ffffff;
  background: #111111;
  border-radius: 50%;
  transition-property: color, background-color, scale;
  transition-duration: 150ms;
  transition-timing-function: cubic-bezier(0.2, 0, 0, 1);
}

.session-mic-orb svg {
  width: 19px;
  height: 19px;
}

.session-mic.is-listening .session-mic-orb {
  color: #111111;
  background: #ffffff;
  scale: 0.92;
}

.listening-dots {
  display: inline-flex;
  gap: 4px;
  align-items: center;
}

.listening-dots span {
  width: 4px;
  height: 4px;
  background: currentColor;
  border-radius: 50%;
  animation: listening-dot 1.25s ease-in-out infinite;
}

.listening-dots span:nth-child(2) {
  animation-delay: 140ms;
}

.listening-dots span:nth-child(3) {
  animation-delay: 280ms;
}

.idea-board {
  position: relative;
  isolation: isolate;
  background:
    radial-gradient(circle at 52% 42%, rgb(255 255 255 / 96%) 0, transparent 48%), #f7f7f5;
}

.idea-board::before {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  content: "";
  background-image: radial-gradient(rgb(17 17 17 / 8%) 0.65px, transparent 0.65px);
  background-size: 18px 18px;
  mask-image: linear-gradient(to right, transparent, black 16%, black 84%, transparent);
  opacity: 0.28;
}

.idea-sticker {
  position: absolute;
  z-index: 1;
  margin: 0;
  padding: 7px;
  overflow: visible;
  color: #111111;
  background: #ffffff;
  border-radius: 14px;
  box-shadow:
    0 0 0 1px rgb(0 0 0 / 5%),
    0 3px 9px rgb(17 17 17 / 8%),
    0 18px 48px rgb(17 17 17 / 10%);
  transition-property: box-shadow;
  transition-duration: 180ms;
  transition-timing-function: cubic-bezier(0.2, 0, 0, 1);
  animation: sticker-enter 520ms cubic-bezier(0.2, 0, 0, 1) backwards;
}

.idea-sticker:hover {
  z-index: 12;
  box-shadow:
    0 0 0 1px rgb(0 0 0 / 7%),
    0 5px 14px rgb(17 17 17 / 10%),
    0 24px 64px rgb(17 17 17 / 15%);
}

.idea-sticker.is-pinned {
  z-index: 11;
  box-shadow:
    0 0 0 2px #111111,
    0 7px 20px rgb(17 17 17 / 12%),
    0 24px 64px rgb(17 17 17 / 16%);
}

.sticker-art {
  overflow: hidden;
  border-radius: 9px;
  outline: 1px solid oklch(0 0 0 / 10%);
}

.sticker-art svg {
  display: block;
  width: 100%;
  height: auto;
}

.sticker-lane {
  position: absolute;
  bottom: 12px;
  left: 12px;
  padding: 4px 7px;
  color: #ffffff;
  background: rgb(17 17 17 / 88%);
  border-radius: 999px;
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.04em;
  line-height: 1;
  text-transform: uppercase;
  backdrop-filter: blur(8px);
}

.pin-button {
  position: absolute;
  top: -14px;
  right: -14px;
  display: grid;
  width: 44px;
  height: 44px;
  padding: 0;
  place-items: center;
  color: #111111;
  background: transparent;
  border: 0;
  border-radius: 50%;
  scale: 1;
  transition-property: color, scale;
  transition-duration: 150ms;
  transition-timing-function: cubic-bezier(0.2, 0, 0, 1);
}

.pin-button::before {
  position: absolute;
  inset: 7px;
  content: "";
  background: rgb(255 255 255 / 96%);
  border-radius: 50%;
  box-shadow:
    0 0 0 1px rgb(0 0 0 / 8%),
    0 4px 14px rgb(17 17 17 / 15%);
  transition-property: background-color;
  transition-duration: 150ms;
  transition-timing-function: cubic-bezier(0.2, 0, 0, 1);
}

.pin-button:hover {
  scale: 1.08;
}

.pin-button:active {
  scale: 0.96;
}

.pin-button:focus-visible {
  outline: 3px solid rgb(49 89 215 / 25%);
  outline-offset: 2px;
}

.pin-button[aria-pressed="true"] {
  color: #ffffff;
}

.pin-button[aria-pressed="true"]::before {
  background: #111111;
}

.pin-button svg {
  position: relative;
  z-index: 1;
  width: 13px;
  height: 13px;
}

.idea-sticker--1 {
  top: 11%;
  left: 4%;
  width: clamp(170px, 28%, 260px);
  rotate: -4deg;
}

.idea-sticker--2 {
  top: 5%;
  left: 54%;
  width: clamp(158px, 25%, 225px);
  rotate: 3.5deg;
  animation-delay: 90ms;
}

.idea-sticker--3 {
  top: 40%;
  left: 29%;
  width: clamp(180px, 31%, 270px);
  rotate: 2deg;
  animation-delay: 40ms;
}

.idea-sticker--4 {
  top: 42%;
  left: 73%;
  width: clamp(145px, 21%, 200px);
  rotate: -3deg;
  animation-delay: 130ms;
}

.idea-sticker--5 {
  top: 67%;
  left: 3%;
  width: clamp(150px, 23%, 210px);
  rotate: -5deg;
  animation-delay: 50ms;
}

.idea-sticker--6 {
  top: 72%;
  left: 56%;
  width: clamp(165px, 26%, 235px);
  rotate: 3deg;
  animation-delay: 140ms;
}

@keyframes workspace-enter {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes sticker-enter {
  from {
    opacity: 0;
    filter: blur(4px);
    transform: translateY(24px) scale(0.92);
  }
  to {
    opacity: 1;
    filter: blur(0);
    transform: translateY(0) scale(1);
  }
}

/*
 * Discovery results: entity, then answer, then evidence, arriving as a wave rather than a
 * flash. Same curve as `workspace-enter` and `sticker-enter` so the pane reads as one system.
 * Staggered with a custom property rather than nth-child, because the number of evidence cards
 * is whatever Cala cited.
 */
.discovery-item {
  animation: discovery-enter 420ms cubic-bezier(0.2, 0, 0, 1) backwards;
  animation-delay: calc(var(--discovery-index, 0) * 60ms);
}

@keyframes discovery-enter {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes listening-dot {
  0%,
  60%,
  100% {
    opacity: 0.28;
    transform: translateY(0);
  }
  30% {
    opacity: 1;
    transform: translateY(-3px);
  }
}

@media (max-width: 767px) {
  .glia-wordmark {
    top: 21px;
    left: 20px;
  }

  .session-settings {
    top: 21px;
    right: 20px;
  }

  .session-hero {
    top: 39%;
  }

  .session-hero h1 {
    font-size: clamp(52px, 17vw, 78px);
  }

  .session-hero > p:last-child {
    max-width: 310px;
    font-size: 16px;
  }

  .session-workspace {
    grid-template-rows: 1fr 1fr;
    grid-template-columns: 1fr;
  }

  .transcript-column {
    order: 2;
    padding: 20px 17px 104px;
  }

  .idea-board {
    order: 1;
  }

  .session-mic {
    top: 68%;
    width: min(260px, calc(100vw - 32px));
  }

  .session-mic[data-docked="true"] {
    width: calc(100vw - 34px);
    transform: translate(calc(-50vw + 17px), calc(32dvh - 17px - 100%));
  }

  .idea-sticker--1 {
    top: 14%;
    left: 0;
    width: 35%;
  }

  .idea-sticker--2 {
    top: 5%;
    left: 58%;
    width: 34%;
  }

  .idea-sticker--3 {
    top: 51%;
    left: 28%;
    width: 38%;
  }

  .idea-sticker--4 {
    top: 50%;
    left: 74%;
    width: 27%;
  }

  .idea-sticker--5,
  .idea-sticker--6 {
    display: none;
  }

  .sticker-lane {
    bottom: 9px;
    left: 9px;
    padding: 3px 5px;
    font-size: 6px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .session-hero,
  .session-workspace,
  .session-mic,
  .session-mic-orb,
  .listening-dots span,
  .idea-sticker,
  .discovery-item,
  .pin-button,
  .pin-button::before,
  .session-settings,
  .settings-segment,
  [data-slot="dialog-overlay"],
  [data-slot="dialog-content"] {
    animation-duration: 1ms;
    animation-iteration-count: 1;
    transition-duration: 1ms;
    transition-delay: 0ms;
  }
}

