import pathlib
p = pathlib.Path("apps/web/src/index.css")
s = p.read_text()

css = '''
/*
 * The pin rail. Fixed to the bottom of the viewport, above the docked microphone, full width and
 * borderless — it is a strip of the canvas rather than a panel on it, so it can appear and
 * disappear without the workspace shifting under it.
 *
 * The docked microphone's own bottom edge is `28px` from the viewport (`top: 67%` plus its
 * translate), and it is 64px tall. `--dock-clearance` keeps those two numbers in one place so
 * the rail cannot drift onto the mic when either moves.
 */
.pin-rail {
  --dock-clearance: 108px;

  position: fixed;
  right: 0;
  bottom: var(--dock-clearance);
  left: 0;
  z-index: 55;
  pointer-events: none;
  animation: workspace-enter 320ms cubic-bezier(0.2, 0, 0, 1) both;
}

.pin-rail-inner {
  display: flex;
  gap: 20px;
  align-items: flex-end;
  justify-content: space-between;
  padding: 0 30px;
  pointer-events: auto;
}

.pin-rail-pins {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 9px;
}

.pin-rail-label {
  margin: 0;
  color: #8f8f8f;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
}

.pin-thumbs {
  display: flex;
  margin: 0;
  padding: 0;
  gap: 10px;
  flex-wrap: wrap;
  list-style: none;
}

.pin-thumb {
  position: relative;
  display: grid;
  width: 48px;
  height: 48px;
  overflow: hidden;
  place-items: center;
  background: #ffffff;
  border-radius: 11px;
  box-shadow:
    0 0 0 1px rgb(0 0 0 / 6%),
    0 3px 10px rgb(17 17 17 / 10%);
  animation: sticker-enter 320ms cubic-bezier(0.2, 0, 0, 1) backwards;
}

.pin-thumb-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/*
 * A sticker has no public URL, so there is no thumbnail and none is faked. The title is what
 * actually reaches the prompt, so the title is what the tile shows.
 */
.pin-thumb-title {
  display: -webkit-box;
  padding: 4px;
  overflow: hidden;
  color: #6f6f6f;
  font-size: 8px;
  font-weight: 550;
  letter-spacing: -0.01em;
  line-height: 1.2;
  text-align: center;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.pin-thumb-remove {
  position: absolute;
  inset: 0;
  display: grid;
  padding: 0;
  place-items: center;
  color: #ffffff;
