  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
}

.pin-thumbs {
  display: flex;
  margin: 0;
  padding: 0;
  gap: 10px;
  flex-wrap: wrap;
  list-style: none;
}

.pin-thumb {
  position: relative;
  display: grid;
  width: 48px;
  height: 48px;
  overflow: hidden;
  place-items: center;
  background: #ffffff;
  border-radius: 11px;
  box-shadow:
    0 0 0 1px rgb(0 0 0 / 6%),
    0 3px 10px rgb(17 17 17 / 10%);
  animation: sticker-enter 320ms cubic-bezier(0.2, 0, 0, 1) backwards;
}

.pin-thumb-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/*
 * A sticker has no public URL, so there is no thumbnail and none is faked. The title is what
 * actually reaches the prompt, so the title is what the tile shows.
 */
.pin-thumb-title {
  display: -webkit-box;
  padding: 4px;
  overflow: hidden;
  color: #6f6f6f;
  font-size: 8px;
  font-weight: 550;
  letter-spacing: -0.01em;
  line-height: 1.2;
  text-align: center;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.pin-thumb-remove {
  position: absolute;
  inset: 0;
  display: grid;
  padding: 0;
  place-items: center;
  color: #ffffff;
  background: rgb(17 17 17 / 62%);
  border: 0;
  opacity: 0;
  transition-property: opacity;
  transition-duration: 140ms;
  transition-timing-function: cubic-bezier(0.2, 0, 0, 1);
}

.pin-thumb:hover .pin-thumb-remove,
.pin-thumb-remove:focus-visible {
  opacity: 1;
}

.pin-thumb-remove:focus-visible {
  outline: 3px solid rgb(49 89 215 / 45%);
  outline-offset: -3px;
}

.pin-thumb-remove svg {
  width: 16px;
  height: 16px;
}

.pin-rail-action {
  display: flex;
  gap: 10px;
  align-items: center;
  justify-content: flex-end;
}

.pin-rail-error {
  max-width: 42ch;
  margin: 0;
  color: #8f8f8f;
  font-size: 12px;
  font-weight: 430;
  letter-spacing: -0.01em;
  line-height: 1.35;
  text-align: right;
  text-wrap: pretty;
}

.pin-generate {
  padding: 13px 22px;
  color: #ffffff;
  font-family: inherit;
  font-size: 14px;
  font-weight: 550;
  letter-spacing: -0.02em;
  line-height: 1;
  background: #111111;
  border: 0;
  border-radius: 999px;
  box-shadow:
    0 1px 1px rgb(17 17 17 / 5%),
    0 9px 28px rgb(17 17 17 / 14%);
  scale: 1;
  transition-property: scale, opacity, background-color;
  transition-duration: 150ms;
  transition-timing-function: cubic-bezier(0.2, 0, 0, 1);
}

.pin-generate:hover:not(:disabled) {
  scale: 1.02;
}

.pin-generate:active:not(:disabled) {
  scale: 0.97;
}

.pin-generate:focus-visible {
  outline: 3px solid rgb(49 89 215 / 25%);
  outline-offset: 3px;
}

.pin-generate:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

/* A quiet pulse rather than a spinner: a spinner asks to be watched, and this takes a moment. */
.pin-generate[data-generating="true"] {
  animation: generate-pulse 1.6s ease-in-out infinite;
  opacity: 1;
}

@keyframes generate-pulse {
  0%,
  100% {
    background: #111111;
  }
  50% {
    background: #4a4a4a;
  }
}

.generated-figure {
  display: flex;
  margin: 0;
  gap: 18px;
  flex-direction: column;
  align-items: flex-start;
}

.generated-image {
  max-width: min(100%, 640px);
  max-height: 58dvh;
  border-radius: 14px;
  box-shadow:
    0 0 0 1px rgb(0 0 0 / 5%),
    0 4px 12px rgb(17 17 17 / 8%),
    0 22px 60px rgb(17 17 17 / 12%);
  object-fit: contain;
}

.generated-caption {
  display: flex;
  max-width: 62ch;
  flex-direction: column;
  gap: 7px;
}

/*
 * The prompt, verbatim. Small and muted because it sits under the image, never truncated or
 * ellipsised: it is the exact string that produced what is above it, and a shortened version of
 * it would be a different claim.
 */
.generated-prompt {
  margin: 0;
  color: #6f6f6f;
  font-size: 13px;
  font-weight: 430;
  letter-spacing: -0.01em;
  line-height: 1.5;
  text-wrap: pretty;
}

.generated-meta {
  display: flex;
  margin: 0;
  gap: 7px;
  flex-wrap: wrap;
  color: #a4a4a4;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.01em;
  line-height: 1;
}

