# 1. Canvas-level layout variables.
s = s.replace(""".session-canvas {
  position: relative;
  min-height: 100dvh;
  overflow: hidden;
  color: #111111;
  background: #f7f7f5;
}""",
""".session-canvas {
  /*
   * The bottom stack, in one place. The pin rail is a banner on the floor of the viewport and
   * the microphone docks above it, so the rail's height is the only number that moves — and
   * `:has()` moves it only while there is a rail to move for.
   */
  --pin-rail-height: 98px;
  --rail-space: 0px;

  position: relative;
  min-height: 100dvh;
  overflow: hidden;
  color: #111111;
  background: #f7f7f5;
}

.session-canvas:has(.pin-rail) {
  --rail-space: var(--pin-rail-height);
}""")

# 2. Mic dock inset now accounts for the rail.
s = s.replace(""".session-mic[data-docked="true"] {
  width: min(164px, calc(29vw - 56px));
  transform: translate(calc(-50vw + 28px), calc(33dvh - 28px - 100%));
}""",
""".session-mic[data-docked="true"] {
  width: min(164px, calc(29vw - 56px));
