input.command:
python3 - <<'PY'
import pathlib, re
p = pathlib.Path("apps/web/src/index.css")
s = p.read_text()

start = s.index("/*\n * The pin rail. Fixed to the bottom")
end = s.index(".pin-rail-action {")
new = '''/*
 * The pin rail. A banner on the floor of the viewport, full width, below the docked microphone.
 *
 * It has its own very light ground rather than sitting transparent on the canvas, because the
 * thumbnails and the button that consumes them are one control and the surface is what says so.
 * Nothing above it is overlapped: `--rail-space` reserves the strip in the workspace grid, the
 * transcript's padding and the microphone's dock offset.
 */
.pin-rail {
  position: fixed;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 65;
  display: flex;
  min-height: var(--pin-rail-height);
  align-items: center;
  background: #fdfdfc;
  box-shadow:
    0 -1px 0 rgb(17 17 17 / 7%),
    0 -12px 32px rgb(17 17 17 / 4%);
  animation: workspace-enter 320ms cubic-bezier(0.2, 0, 0, 1) both;
}

.pin-rail-inner {
  display: flex;
  width: 100%;
  gap: 20px;
  align-items: center;
  justify-content: space-between;
  padding: 0 30px;
}

.pin-rail-pins {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 9px;
}

.pin-rail-label {
  margin: 0;
  color: #8f8f8f;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
}

/*
 * One row, always. Pins scroll sideways rather than wrapping, so the banner's height is a
 * constant the layout above it can reserve.
 */
.pin-thumbs {
  display: flex;
  margin: 0;
  padding: 0;
  gap: 10px;
  flex-wrap: nowrap;
  overflow-x: auto;
  list-style: none;
  overscroll-behavior-x: contain;
  scrollbar-width: none;
}

.pin-thumbs::-webkit-scrollbar {
  display: none;
}

.pin-thumb {
  position: relative;
  display: grid;
  width: 48px;
  height: 48px;
  flex: 0 0 auto;
  overflow: hidden;
  place-items: center;
  background: #ffffff;
  border-radius: 11px;
  box-shadow:
    0 0 0 1px rgb(0 0 0 / 6%),
    0 3px 10px rgb(17 17 17 / 10%);
  animation: sticker-enter 320ms cubic-bezier(0.2, 0, 0, 1) backwards;
}

.pin-thumb-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/*
 * A sticker has no public URL, so there is no thumbnail and none is faked. The title is what
 * actually reaches the prompt, so the title is what the tile shows — clamped, with the full
 * string on the tile's `title` and in the unpin button's label.
 */
.pin-thumb-title {
  display: -webkit-box;
  padding: 15px 4px 4px;
  overflow: hidden;
  color: #6f6f6f;
  font-size: 8px;
  font-weight: 550;
  letter-spacing: -0.01em;
  line-height: 1.2;
  overflow-wrap: anywhere;
  text-align: center;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

/* Always on screen: unpinning is half of what this rail is for. */
.pin-thumb-remove {
  position: absolute;
  top: 3px;
  right: 3px;
  display: grid;
  width: 22px;
  height: 22px;
  padding: 0;
  place-items: center;
  color: #ffffff;
  background: rgb(17 17 17 / 78%);
  border: 0;
  border-radius: 50%;
  opacity: 0.92;
  scale: 1;
  transition-property: opacity, scale, background-color;
  transition-duration: 140ms;
  transition-timing-function: cubic-bezier(0.2, 0, 0, 1);
}

.pin-thumb-remove:hover {
  opacity: 1;
  background: #111111;
  scale: 1.08;
}

.pin-thumb-remove:active {
  scale: 0.94;
}

.pin-thumb-remove:focus-visible {
  opacity: 1;
  outline: 3px solid rgb(49 89 215 / 45%);
  outline-offset: 1px;
}

.pin-thumb-remove svg {
  width: 12px;
  height: 12px;
}

'''
s = s[:start] + new + s[end:]

# Mobile: shorter banner, and the error line still has nowhere to go.
s = s.replace("""  .pin-rail {
    --dock-clearance: 95px;
  }

  .pin-rail-inner {""",
"""  .session-canvas {
    --pin-rail-height: 92px;
  }

  .pin-rail-inner {""")
p.write_text(s)
print("ok")
PY
grep -n "dock-clearance\|pin-rail::before" apps/web/src/index.css || echo "old rail rules fully removed"

