188	function encodePcm24k(input: Float32Array, inputSampleRate: number): string {
189	  const ratio = inputSampleRate / PCM_SAMPLE_RATE
190	  const outputLength = Math.max(1, Math.floor(input.length / ratio))
191	  const bytes = new Uint8Array(outputLength * 2)
192	  const view = new DataView(bytes.buffer)
193	
194	  for (let outputIndex = 0; outputIndex < outputLength; outputIndex += 1) {
195	    const start = Math.floor(outputIndex * ratio)
196	    const end = Math.max(start + 1, Math.min(input.length, Math.floor((outputIndex + 1) * ratio)))
197	    let sum = 0
198	    for (let inputIndex = start; inputIndex < end; inputIndex += 1) {
199	      sum += input[inputIndex] ?? 0
200	    }
201	    const sample = Math.max(-1, Math.min(1, sum / (end - start)))
202	    view.setInt16(outputIndex * 2, sample < 0 ? sample * 0x8000 : sample * 0x7fff, true)
203	  }
204	
205	  let binary = ''
206	  for (let index = 0; index < bytes.length; index += 1) {
207	    binary += String.fromCharCode(bytes[index] ?? 0)
208	  }
209	  return window.btoa(binary)
210	}
